```typescript
function removeDuplicados(valores: string[]): string[] {
  const valoresMap = new Map<string, number>();
  for (const valor of valores) {
    if (valoresMap.has(valor)) {
      valoresMap.set(valor, valoresMap.get(valor) + 1);
    } else {
      valoresMap.set(valor, 1);
    }
  }
  const arrayValores = Array.from(valoresMap.keys()).filter((valor) => valoresMap.get(valor) === 1);
  return arrayValores.map((valor) => valor);
}

console.assert(removeDuplicados(['ana', 'bia', 'ana', 'caio', 'bia']) ,['ana', 'bia', 'caio']);
console.assert(removeDuplicados([]) ,[]);
console.assert(removeDuplicados(['x']) ,['x']);
